DATA_MASK = 0x7F
CONTINUATION_FLAG = 0x80


def encode(numbers):
    encoded = []
    for number in numbers:
        encoded.extend(_encode_one(number))
    return encoded


def _encode_one(number):
    chunks = [number & DATA_MASK]
    number >>= 7

    while number:
        chunks.append(CONTINUATION_FLAG | (number & DATA_MASK))
        number >>= 7

    chunks.reverse()
    return chunks


def decode(bytes_):
    values = []
    number = 0
    incomplete = False

    for byte in bytes_:
        number = (number << 7) | (byte & DATA_MASK)
        if byte & CONTINUATION_FLAG:
            incomplete = True
        else:
            values.append(number)
            number = 0
            incomplete = False

    if incomplete:
        raise ValueError("incomplete sequence")

    return values

